/*
 * A045806  6-ish numbers (end in 23, 27, 61, 89).
 * https://oeis.org/A045806
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   not stated
 * Range:     u8 n <= 10, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A045806 – 6‑ish numbers (end in 23, 27, 61, 89)
 *  The sequence is generated by a periodic difference pattern:
 *  d₁ = 4, d₂ = 34, d₃ = 28, d₄ = 34, and then the pattern repeats.
 *  Thus a(n) = 23 + 100·⌊(n-1)/4⌋ + prefix[(n-1) mod 4],
 *  where prefix = {0, 4, 38, 66}.
 *  This implementation works for any seq_t, idx_t and runs in O(1).
 */
seq_t a(idx_t n)
{
    /*  The first value is defined for n >= 1.  For n < 1 the return value
     *  is irrelevant because the sequence is defined only for n >= 1.
     */
    if (n < 1) return 0;

    /*  Compute quotient and remainder of (n-1) divided by 4.  All of these
     *  arithmetic operations use idx_t which is guaranteed to be an unsigned
     *  type large enough for the index.
     */
    idx_t q = (n - 1) / 4;      /* floor((n-1)/4)   */
    idx_t r = (n - 1) % 4;      /* (n-1) mod 4      */

    /*  Prefix sums for the four possible partial cycles.  The first element
     *  corresponds to r == 0 (no additional steps beyond the complete cycles).
     */
    static const seq_t prefix[4] = {
        (seq_t)0,   /* r == 0  -> add 0  */
        (seq_t)4,   /* r == 1  -> add 4  */
        (seq_t)38,  /* r == 2  -> add 38 */
        (seq_t)66   /* r == 3  -> add 66 */
    };

    /*  Assemble the value: 23 + 100·q + prefix[r]  */
    seq_t val = (seq_t)23 + (seq_t)100 * q + prefix[(unsigned)r];
    return val;
}
